  "body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n    <title>Add Site</title>\n</head>\n<body>\n    <nav class=\"navbar navbar-expand-lg navbar-dark bg-dark\">\n        <div class=\"container-fluid\">\n            <a class=\"navbar-brand\" href=\"#\">SiteSaver</a>\n            <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarNav\" aria-controls=\"navbarNav\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n                <span class=\"navbar-toggler-icon\"></span>\n            </button>\n            <div class=\"collapse navbar-collapse\" id=\"navbarNav\">\n                <ul class=\"navbar-nav\">\n                    <li class=\"nav-item\">\n                        <a class=\"nav-link active\" aria-current=\"page\" href=\"/add_url\">Add Site</a>\n                    </li>\n                    <li class=\"nav-item\">\n                        <a class=\"nav-link\" href=\"/\">View Saved Sites</a>\n                    </li>\n                </ul>\n            </div>\n        </div>\n    </nav>\n<div class=\"container mt-4\">\n    <h1>Add Site Url</h1>\n    \n    \n\n    <form method=\"POST\"   class=\"mb-3\">\n        <div class=\"mb-3\">\n            <label for=\"url\" class=\"form-label\">URL</label>\n            <input type=\"text\" class=\"form-control\" id=\"url\" name=\"url\" placeholder=\"Enter URL here\" required>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary\">Submit</button>\n    </form>\n</div>\n\n<script src=\"https://code.jquery.com/jquery-3.5.1.min.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/@popperjs/core@2.5.3/dist/umd/popper.min.js\"></script>\n<script src=\"https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/js/bootstrap.min.js\"></script>\n<script> \n    // form submit \n    $('form').submit(function(e) {\n        e.preventDefault();\n        var url = $('#url').val();\n        $.ajax({\n            url: '/add_url',\n            type: 'POST',\n            data: {url: url},\n            success: function(response) {\n                alert(response.message);\n                if (response.success == true) {\n                    window.location.href = response.redirect;\n                    \n                }  \n            }\n        });\n        \n    });\n</script>\n</body>\n</html>",
  "burp": "not routed through Burp"
}"}

