@app.route('/delete_url/<int:url_id>', methods=['POST'])
def delete_url(url_id):
    url = URL.query.get_or_404(url_id)
    db.session.delete(url)
    db.session.commit()
    flash('URL deleted successfully!', 'success')
    return redirect('/')

